import json

baseline = json.load(open('baseline-packages.json'))
after = json.load(open('after-cpm-packages.json'))

def get_pkgs(data):
    result = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        for f in p['frameworks']:
            for pkg in f['topLevelPackages']:
                key = (name, f['framework'], pkg['id'])
                result[key] = pkg['resolvedVersion']
    return result

b = get_pkgs(baseline)
a = get_pkgs(after)

print('=== CHANGES ===')
changes = False
for key in sorted(set(list(b.keys()) + list(a.keys()))):
    bv = b.get(key, 'MISSING')
    av = a.get(key, 'MISSING')
    if bv != av:
        changes = True
        print(f'{key[0]} [{key[1]}] {key[2]}: {bv} -> {av}')

if not changes:
    print('No changes - all packages resolve identically')

print()
print('=== UNCHANGED ===')
for key in sorted(b.keys()):
    if b[key] == a.get(key):
        print(f'{key[0]} [{key[1]}] {key[2]}: {b[key]}')
"

